    variables,
    alert_instance_id: resolved.alert_instance_id || null,
    performed_by: resolved.performed_by || null
  }
}];

const items = $input.all().map((e) => e.json);

if (items.length < 1) {
  return { data: [] };
}

return { data: items };

function toWhatsAppFormat(text) {
  return (
    text
      // Bloques de código: preservarlos para no tocar su contenido interno
      .replace(
        /```([\s\S]*?)```/g,
        (_, code) => `\u0000${Buffer.from(code).toString("base64")}\u0000`,
      )

      // Negrita+cursiva combinada -> cursiva+negrita anidada de WhatsApp
      .replace(/\*\*\*(.+?)\*\*\*/g, "*_$1_*")

      // Negrita: **x** o __x__ -> *x*
      .replace(/\*\*(.+?)\*\*/g, "*$1*")
      .replace(/__(.+?)__/g, "*$1*")

      // Tachado: ~~x~~ -> ~x~
      .replace(/~~(.+?)~~/g, "~$1~")

      // Código inline simple -> lo dejamos sin backticks (o como *x* si preferís destacarlo)
      .replace(/`([^`]+?)`/g, "$1")

      // Links markdown [texto](url) -> "texto: url"
      .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, "$1: $2")

      // Headers -> negrita simple
      .replace(/^#{1,6}\s*(.+)$/gm, "*$1*")

      // Líneas horizontales sueltas
      .replace(/^[\s]*[-*_]{3,}[\s]*$/gm, "")

      // Bullets -> guión simple
      .replace(/^[ \t]*[\*\-][ \t]+/gm, "- ")

      .replace(/[ \t]{2,}/g, " ")
      .replace(/\n{3,}/g, "\n\n")

      // Restaurar bloques de código
      .replace(
        /\u0000([\s\S]*?)\u0000/g,
        (_, b64) => "```" + Buffer.from(b64, "base64").toString() + "```",
      )
      .trim()
  );
}

const raw = $input.first().json.output;
// Marcador interno que el agente deja como última línea (<<PENDING:SI>> / <<PENDING:NO>>) para
// que el flujo de reintento sepa si quedó algo pendiente, sin que el paciente lo vea nunca.
const pendingMatch = raw.match(/<<PENDING:(SI|NO)>>\s*$/i);
const pending = pendingMatch ? pendingMatch[1].toUpperCase() === "SI" : false;
const withoutMarker = pendingMatch ? raw.slice(0, pendingMatch.index).trim() : raw;

return { output: toWhatsAppFormat(withoutMarker), pending };

