// Junta los mensajes reclamados en un unico texto para el agente y separa los
// adjuntos (imagen / PDF) para el flujo de ordenes.
// Si otra ejecucion ya se llevo el lote (0 filas), corta el flujo silenciosamente.
const rows = $input.all().map(i => i.json);

const parts = rows
  .map(r => (r.message_text || ''))
  .filter(t => typeof t === 'string' && t.trim() !== '');

const MAX_FILES = 6;
const allMedia = rows
  .filter(r => r.media_kind && r.media_url)
  .map(r => ({
    wamid: r.wamid,
    kind: r.media_kind,
    id: r.media_id || '',
    url: r.media_url,
    mime: r.media_mime || '',
    sha256: r.media_sha256 || '',
    filename: r.media_filename || '',
    caption: r.media_caption || ''
  }));

if (parts.length === 0 && allMedia.length === 0) {
  return [];
}

const extract = $('Filter & Extract Inbound Message').first().json;

return [{
  json: {
    from_phone: extract.from_phone,
    wamid: extract.wamid,
    message_text: parts.join(String.fromCharCode(10)),
    batch_size: rows.length,
    has_media: allMedia.length > 0,
    media: allMedia.slice(0, MAX_FILES),
    media_overflow: Math.max(0, allMedia.length - MAX_FILES)
  },
  pairedItem: { item: 0 }
}];

// whatsapp.smb.message.echoes es un evento de "coexistence" de Meta: se dispara
// EXCLUSIVAMENTE para mensajes enviados a mano desde la app de WhatsApp Business
// o un dispositivo vinculado, nunca para mensajes enviados por la API (ver
// https://developers.facebook.com/docs/whatsapp/cloud-api/webhooks/reference/smb_message_echoes/).
// Como el bot siempre envía por API (Send Reply / Send Followup Message / Send via
// YCloud1), todo lo que llega acá es, por definición, un mensaje escrito a mano por
// alguien del equipo -- no hace falta distinguir "eco propio" de "mensaje humano".
const body = $('POST wa-message-sent').first().json.body || {};
const msg = body.whatsappMessage || {};

const isTextEcho = body.type === 'whatsapp.smb.message.echoes'
  && msg.type === 'text'
  && typeof msg.text?.body === 'string'
  && msg.text.body.trim() !== ''
  && !!msg.to;

const phone = '+' + String(msg.to || '').replace(/\D/g, '');

return [{
  json: {
    is_text_echo: isTextEcho,
    phone,
    message_text: msg.text?.body || ''
  }
}];

