// Un item por archivo. El id del intake es el source_id con el que se guardan los originales.
const intakeId = $('Get Or Create Intake').first().json.id;
const ctx = $('Combine Buffered Messages').first().json;
return ctx.media.map((f, idx) => ({ json: {
  intake_id: intakeId,
  phone: ctx.from_phone,
  seq: idx,
  wamid: f.wamid,
  kind: f.kind,
  media_id: f.id,
  url: f.url,
  mime: f.mime,
  sha256_b64: f.sha256,
  filename: f.filename,
  caption: f.caption
} }));

// Valida cada descarga y arma los metadatos de auditoria.
// - Con neverError una respuesta 4xx/5xx llega igual: se detecta por tipo, tamano o hash.
// - YCloud informa el sha256 (base64) del archivo original: si no coincide con lo descargado,
//   la descarga esta corrupta o no es el archivo.
const crypto = require('crypto');
const MAX_BYTES = 10 * 1024 * 1024;
const metas = $('Split Media Files').all().map(i => i.json);
const EXT = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'application/pdf': 'pdf' };

const out = [];
const items = $input.all();
for (let i = 0; i < metas.length; i++) {
  const meta = metas[i];
  const item = items[i];
  const base = { ...meta, received_at: new Date().toISOString() };
  let reason = null, buf = null;

  if (!item || !item.binary || !item.binary.data) {
    reason = 'download_failed';
  } else {
    buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    const gotMime = String(item.binary.data.mimeType || '').toLowerCase().split(';')[0].trim();
    if (buf.length === 0) reason = 'empty_file';
    else if (buf.length > MAX_BYTES) reason = 'too_large';
    else if (gotMime && meta.mime && gotMime !== meta.mime) reason = 'unexpected_mime';
  }

  let sha256 = null;
  if (buf && buf.length > 0) {
    const raw = crypto.createHash('sha256').update(buf).digest();
    sha256 = raw.toString('hex');
    if (!reason && meta.sha256_b64 && raw.toString('base64') !== meta.sha256_b64) reason = 'hash_mismatch';
  }

  const ext = EXT[meta.mime] || 'bin';
  const fileName = `${meta.wamid || ('media-' + i)}.${ext}`;
  const json = { ...base, ok: !reason, reject_reason: reason, sha256, size: buf ? buf.length : 0, file_name: fileName };
  const entry = { json };
  if (!reason && item && item.binary) {
    entry.binary = { data: { ...item.binary.data, fileName, mimeType: meta.mime } };
  }
  out.push(entry);
}
return out;

// Arma la referencia del original guardado. El orden de salida de 'Attachements CRUD'
// coincide con el de los archivos que pasaron 'Media OK?'.
const metas = $('Validate Media').all().map(i => i.json).filter(j => j.ok);
const res = $input.all();
return res.map((r, k) => {
  const j = metas[k] || {};
  const up = r.json || {};
  const attachmentId = up.success === true && up.data ? (up.data.id ?? null) : null;
  return { json: {
